"""Implementation of actions for the Staff Schedule Rights UI in the Mosaiq application"""
from interops.libraries.mosaiq.interactions.objects.mosaiq_staff_schedule_rights_objects import ScheduleRightsObjects
from interops.libraries.common.state import State
from interops.libraries.squish_actions import CommonActions

class StaffScheduleRights():
    def __init__(self):
        self.default_private_appointments = State(ScheduleRightsObjects.default_Private_Appointments_CheckBox)

    @property
    def restricted(self):
        self._restricted = CommonActions.get_text(ScheduleRightsObjects.restricted_Pane) == "Yes"
        return self._restricted

    @restricted.setter
    def restircted(self, value: bool):
        CommonActions.left_click_object(ScheduleRightsObjects.restricted_Pane)
        if value != (CommonActions.get_text(ScheduleRightsObjects.restricted_Pane) == "Yes"):
            CommonActions.press_key_sequence("Y" if value else "N")

    def click_select(self, which: int):
        if which == 1:
            btn = ScheduleRightsObjects.staff_1_Select_Button
        elif which == 2:
            btn = ScheduleRightsObjects.staff_2_Select_Button
        elif which == 3:
            btn = ScheduleRightsObjects.staff_3_Select_Button
        elif which == 4:
            btn = ScheduleRightsObjects.staff_4_Select_Button
        elif which == 5:
            btn = ScheduleRightsObjects.staff_5_Select_Button
        else:
            raise ValueError
        CommonActions.left_click_object(btn)

    def click_ok(self):
        CommonActions.left_click_object(ScheduleRightsObjects.oK_Button)

    def click_cancel(self):
        CommonActions.left_click_object(ScheduleRightsObjects.cancel_Button)
